using System;using System.Linq;using NUnit.Framework;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Tilemaps;namespace Rootborn.Tests.EditMode.Interiors{public sealed class UrbanGroundArtAssetTests{
[TestCase("paving")][TestCase("grass")]public void GroundUsesOneCellPointSpriteAndNonBlockingAddressableTile(string name){string root="Assets/Art/UrbanStreet/Ground31/UrbanGround_"+name+"_48.png";var s=AssetDatabase.LoadAssetAtPath<Sprite>(root);Assert.That(s,Is.Not.Null);Assert.That(s.rect.size,Is.EqualTo(new Vector2(48,48)));Assert.That(s.pivot,Is.EqualTo(new Vector2(24,24)));Assert.That(s.pixelsPerUnit,Is.EqualTo(48));var i=(TextureImporter)AssetImporter.GetAtPath(root);Assert.That(i.filterMode,Is.EqualTo(FilterMode.Point));Assert.That(i.mipmapEnabled,Is.False);var t=AssetDatabase.LoadAssetAtPath<Tile>("Assets/Data/Interiors/TileSets/UrbanGround31/UrbanGround_"+name+".asset");Assert.That(t,Is.Not.Null);Assert.That(t.sprite,Is.SameAs(s));Assert.That(t.colliderType,Is.EqualTo(Tile.ColliderType.None));}
[Test]public void CampusGroundOverlayMatchesAllAuthoredDistrictCellsWithoutNewColliders(){var scene=EditorSceneManager.OpenScene("Assets/Scenes/Town.unity",OpenSceneMode.Additive);try{var maps=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Tilemap>(true)).ToArray();var original=maps.Single(m=>m.name=="DistrictGround");var overlay=maps.SingleOrDefault(m=>m.name=="CampusCalmGround");Assert.That(overlay,Is.Not.Null);Assert.That(overlay.transform.parent.name,Is.EqualTo("SchoolPlazaUrbanProps"));Assert.That(overlay.GetComponent<Collider2D>(),Is.Null);Assert.That(overlay.GetComponent<TilemapRenderer>().sortingOrder,Is.EqualTo(2));int road=0,grass=0;foreach(var c in original.cellBounds.allPositionsWithin){var old=original.GetTile(c);if(old==null)continue;bool isRoad=AssetDatabase.GetAssetPath(old).EndsWith("/road_paver.asset");var tile=overlay.GetTile<Tile>(c);Assert.That(tile,Is.Not.Null);Assert.That(AssetDatabase.GetAssetPath(tile),Does.EndWith(isRoad?"UrbanGround_paving.asset":"UrbanGround_grass.asset"));Assert.That(overlay.GetCellCenterWorld(c),Is.EqualTo(original.GetCellCenterWorld(c)));if(isRoad)road++;else grass++;}int total=0;foreach(var c in overlay.cellBounds.allPositionsWithin)if(overlay.HasTile(c))total++;Assert.That(road,Is.EqualTo(718));Assert.That(grass,Is.EqualTo(3170));Assert.That(total,Is.EqualTo(3888));}finally{EditorSceneManager.CloseScene(scene,true);}}
}}
